/* @lc app=leetcode id=2801 lang=kotlin */
class Solution { fun countSteppingNumbers(low: String, high: String): Int = (1000000007L).let { mod -> { s: String -> LongArray(4444) { -1L }.let { memo -> DeepRecursiveFunction<IntArray, Long> { args -> (args[0] * 44 + args[1] * 4 + args[2] * 2 + args[3]).let { key -> memo[key].let { memoized -> if (memoized != -1L) memoized else (0..if (args[2] == 1) 9 else s[args[0]] - '0').sumOf { d -> if (args[3] == 0) callRecursive(intArrayOf(args[0] + 1, d, if (args[2] == 1 || d < s[args[0]] - '0') 1 else 0, if (d > 0) 1 else 0)) else if (java.lang.Math.abs(d - args[1]) == 1) callRecursive(intArrayOf(args[0] + 1, d, if (args[2] == 1 || d < s[args[0]] - '0') 1 else 0, 1)) else 0L }.also { memo[key] = it % mod } } } }.call(intArrayOf(0, 0, 0, 0)) } } }.let { f -> ((f(high) - f(low) + (if (low.zipWithNext { a, b -> java.lang.Math.abs(a - b) == 1 }.all { it }) 1L else 0L)) % mod + mod) % mod }.toInt() } }